def func(lists, k):
  """
  :param lists: list of lists of sorted and distinct integers
  :param k: number of integers to return
  :return: the top k integers that occur most frequently
  """
  import heapq

  freq = {}
  for lst in lists:
      for num in lst:
          freq[num] = freq.get(num, 0) + 1

  top_k = heapq.nlargest(k, freq, key=freq.get)

  return top_k

def find_top_k_integers(lists, k):
  """
  Find the top k integers that occur most frequently from given lists of sorted and distinct integers using heap queue algorithm.
  :param lists: list of lists of integers
  :param k: integer
  :return: list of top k integers
  """
  heap = []
  counts = {}
  for lst in lists:
      for num in lst:
          if num not in counts:
              counts[num] = 1
          else:
              counts[num] += 1
  for num, count in counts.items():
      heapq.heappush(heap, (-count, num))
  result = []
  for _ in range(k):
      _, num = heapq.heappop(heap)
      result.append(num)
  return result

def func(lists, k):

  # Create a dictionary to store the counts of each integer
  counts = {}
  for lst in lists:
      for num in lst:
          counts[num] = counts.get(num, 0) + 1

  # Create a heap queue to store the top k integers
  heap = []

  # Loop through the counts dictionary and add the top k integers to the heap
  for num, count in counts.items():
      heapq.heappush(heap, (count, num))
      if len(heap) > k:
          heapq.heappop(heap)

  # Return the top k integers in the heap
  return [num for count, num in heap]

