def next_smallest_palindrome(n):
  n = str(n)
  if len(n) == 1:
      return int(n) + 1
  elif len(n) == 2:
      if n[0] == n[1]:
          return int(n[0] + str(int(n[0]) + 1))
      else:
          return int(n[0] + str(int(n[0]) + 1) + n[1])
  else:
      mid = len(n) // 2
      left = n[:mid]
      right = n[mid:]
      if left == right:
          return int(n + str(int(n[0]) + 1))
      else:
          return int(left + str(int(right[0]) + 1) + right[1:])

