def is_valid_parenthese(s):
  stack = []
  for char in s:
      if char == "(" or char == "[" or char == "{":
          stack.append(char)
      elif char == ")" or char == "]" or char == "}":
          if not stack:
              return False
          top = stack.pop()
          if (char == ")" and top != "(") or (char == "]" and top != "[") or (char == "}" and top != "{"):
              return False
  return not stack

