def common_prefix(strings, k):
  """
  Find the longest common prefix in the given set of strings.
  :param strings: a list of strings
  :param k: the number of strings to consider
  :return: the longest common prefix
  """
  if k == 0:
      return ""
  for i in range(len(strings[0])):
      char = strings[0][i]
      for j in range(1, k):
          if i >= len(strings[j]) or char != strings[j][i]:
              return strings[0][:i]
  return strings[0][:i+1]

