def parabola_focus(a,b,c):
  x = -b/(2*a)
  y = (-b*b)/(4*a*c)
  return (x, y)

def parabola_focus(a, b, c):
  discriminant = b**2 - 4*a*c
  if discriminant < 0:
      return None
  else:
      x1 = (-b + math.sqrt(discriminant)) / (2*a)
      x2 = (-b - math.sqrt(discriminant)) / (2*a)
      y1 = a*x1**2 + b*x1 + c
      y2 = a*x2**2 + b*x2 + c
      return (x1, y1), (x2, y2)

def parabola_focus(a,b,c):
  x = (-b/(2*a))
  y = (-(b**2-4*a*c)/(4*a))
  return (x, y)

def parabola_focus(a, b, c):
  focus_x = (-b/(2*a))
  focus_y = (focus_x**2)/a + b/a + c/a
  return (focus_x, focus_y)

