def longest_common_subsequence(seq1, seq2, n, m):
  dp = [[0] * (m+1) for _ in range(n+1)]

  for i in range(1, n+1):
      for j in range(1, m+1):
          if seq1[i-1] == seq2[j-1]:
              dp[i][j] = dp[i-1][j-1] + 1
          else:
              dp[i][j] = max(dp[i-1][j], dp[i][j-1])

  return dp[n][m]

