  """
  Returns the length of the longest repeating subsequence of s
  such that the two subsequences don't have same string characters
  at same positions.
  """
  s_len = len(s)
  dp = [0] * (s_len + 1)
  for i in range(1, s_len + 1):
      for j in range(i + 1, s_len + 1):
          if s[i - 1] != s[j - 1]:
