def is_majority(arr, n, x):
  """
  Given a sorted array arr of size n and an element x,
  check if x is the majority element in the array.
  """
  left = 0
  right = n - 1
  while left <= right:
      if arr[left] == x and arr[right] == x:
          return True
      if arr[left] != x:
          left += 1
      if arr[right] != x:
          right -= 1
  return False

def is_majority(arr, n, m):
