  while left <= right:
      if arr[left] == m and arr[right] == m:
          return True
      if arr[left] == m:
          left += 1
      if arr[right] == m:
          right -= 1
  return False

def is_majority(arr, n, k):
  """
  Returns True if there exists a majority element in the array such that
  it appears more than n/k times, and False otherwise.
  """
  left, right = 0, n-1
  while left <= right:
      if arr[left] == k:
          left += 1
      if arr[right] == k:
          right -= 1
      if left > right:
          return True
  return False

def is_majority(arr, n, majority_elem):
