  return left == n or right == -1

def is_majority(arr, n, candidate):
  """
  Given a sorted array arr and a candidate element,
  return True if the candidate is a majority element,
  i.e. it occurs more than (n/2) times in the array.
  """
  left = 0
  right = len(arr) - 1
  while left <= right:
      mid = (left + right) // 2
      if arr[mid] == candidate:
          if mid > 0 and arr[mid - 1] == candidate:
              left = mid + 1
          elif mid + 1 < len(arr) and arr[mid + 1] == candidate:
              right = mid - 1
          else:
              count = 1
              while mid - 1 >= 0 and arr[mid - 1] == candidate:
                  mid -= 1
                  count += 1
              while mid + 1 < len(arr) and arr[mid + 1] == candidate:
                  mid += 1
                  count += 1
              if count > n // 2:
                  return True
              else:
                  return False
      elif arr[mid] < candidate:
          left = mid + 1
      else:
          right = mid - 1
  return False

