  Check if there is a majority element in the sorted array.
  """
  low = 0
  high = n - 1
  while low <= high:
      mid = (low + high) // 2
      if arr[mid] > k:
          high = mid - 1
      elif arr[mid] < k:
          low = mid + 1
      else:
          break
  if low > high:
      return False
  left = mid - 1
  right = mid + 1
  while left >= 0 and arr[left] == k:
      left -= 1
  while right < n and arr[right] == k:
      right += 1
  return right - left - 1 > n // 2

