  Given a sorted array arr of size n and an integer k,
  find if there exists a number that appears more than n/k times.
  """
  left, right = 0, n-1
  while left <= right:
      if arr[left] == arr[right]:
          if right - left + 1 > n//k:
              return True
          else:
              return False
      elif arr[left] > arr[right]:
          right -= 1
      else:
          left += 1
  return False

