def No_of_Triangle(base, height):
  if base < height:
      return -1
  return (base * height) // 2

def No_of_Triangle(n, m):
  if n < m:
      return -1
  if n == m:
      return 1
  return No_of_Triangle(n-1, m-1) + No_of_Triangle(n-1, m) + No_of_Triangle(n, m-1)

def No_of_Triangle(n, m):
  if n < 3 or m < 3:
      return -1
  else:
      return (n-1) * (m-1) * (n-2) // 2

