  count = 0
  for i in range(n):
      count += (m - i) // 2
  return count

def get_total_number_of_sequences(n, m):
  """
  Returns the number of possible sequences of length n such that each of the next element is greater than or equal to twice of the previous element but less than or equal to m.
  """
  return (m ** n) - (2 ** n)

def get_total_number_of_sequences(n, m):
  if n == 1:
      return 1
