def lps(s):
  """
  Find the longest palindromic subsequence in the given string.

  Args:
      s (str): The input string.

  Returns:
      int: The length of the longest palindromic subsequence.
  """
  # Initialize the dp table with 0s
  dp = [0] * (len(s) + 1)

  # Loop through the input string and fill the dp table
  for i in range(1, len(s) + 1):
      for j in range(i, 0, -1):
          if s[i - 1] == s[j - 1] and j - i < 2:
              dp[i] = max(dp[i], dp[j] + 1)
          elif s[i - 1] == s[j - 1]:
              dp[i] = max(dp[i], dp[j - 1] + 1)

  # Return the maximum value in the dp table
  return max(dp)

