def max_sub_array_sum_repeated(arr, k, n):
  # Initialize variables
  max_sum = 0
  current_sum = 0
  repeated_arr = [arr[i] for i in range(len(arr))]

  # Repeat the array k times
  for i in range(k):
      repeated_arr += arr

  # Calculate the maximum sum of the contiguous subarray
  for i in range(len(repeated_arr)):
      current_sum += repeated_arr[i]
      if current_sum > max_sum:
          max_sum = current_sum
      elif current_sum < 0:
          current_sum = 0

  return max_sum

