def count_no_of_ways(n, k):
  """
  Returns the number of ways of painting the fence such that at most 2 adjacent posts have the same color
  for the given fence with n posts and k colors.
  """
  # Initialize the dp table with 0s
  dp = [[0] * k for _ in range(n+1)]

  # Initialize the first row with 1
  for i in range(k):
      dp[0][i] = 1

  # Fill in the dp table
  for i in range(1, n+1):
      for j in range(k):
          if i == 1:
              dp[i][j] = 1
          else:
              dp[i][j] = dp[i-1][j] + dp[i-2][j]

  return dp[n][k-1]

