def max_sum_rectangular_grid(grid, n):
  """
  Find the maximum sum such that no two chosen numbers are adjacent
  for the given rectangular grid of dimension 2 x n.
  """
  m = len(grid)
  dp = [[0] * n for _ in range(m)]
  for i in range(m):
      for j in range(n):
          if i == 0 or j == 0:
              dp[i][j] = grid[i][j]
          else:
              dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]
  return dp[m - 1][n - 1]

