  for i in range(len(grid)):
      # Loop through each column of the current row
      for j in range(len(grid[i])):
          # If the current element is not adjacent to any previously selected element, add it to the sum
          if not (i == start_i + 1 and j == start_j) and not (i == start_i - 1 and j == start_j) and not (i == start_i and j == start_j + 1) and not (i == start_i and j == start_j - 1):
              max_sum += grid[i][j]

  return max_sum

