  Returns the index of the last occurrence of the target in the sorted array arr.
  If the target is not found in the array, returns -1.
  """
  left = 0
  right = len(arr) - 1
  while left <= right:
      mid = (left + right) // 2
      if arr[mid] == target:
          if mid == len(arr) - 1 or arr[mid+1] != target:
              return mid
          else:
              right = mid - 1
      elif arr[mid] < target:
          left = mid + 1
      else:
          right = mid - 1
  return -1

