      for j in range(n):
          # If the current cell is not blocked, add the gold from the current cell to the dp table
          if mine[i][j] != 0:
              dp[i][j] = mine[i][j]
          # If the current cell is blocked, check if the cell above or to the left is not blocked
          else:
              # If the cell above is not blocked, add the gold from the current cell to the dp table
              if i > 0 and dp[i - 1][j] != 0:
                  dp[i][j] = dp[i - 1][j]
              # If the cell to the left is not blocked, add the gold from the current cell to the dp table
              elif j > 0 and dp[i][j - 1] != 0:
